99		if body, ok := caddyhttp.GetVar(req.Context(), "extended_connect_websocket_body").(io.ReadCloser); ok {
100			req.Body = body
101			rw.Header().Del("Upgrade")
102			rw.Header().Del("Connection")
103			delete(rw.Header(), "Sec-WebSocket-Accept")
